 \begin{equation}
  \mathcal{C} =
  \begin{bmatrix}
    0 & \dfrac{1}{m} \\
    \dfrac{1}{m} & -\dfrac{\Gamma}{m} \\
  \end{bmatrix}
  \label{controllability_matrix}
